SELECT ?z ?label ?sensor ?ext WHERE {
  ?z a <https://brickschema.org/schema/Brick#Zone> ;
     rdfs:label ?label ;
     <https://brickschema.org/schema/Brick#hasPoint> ?sensor .
  FILTER(regex(?label, "Perimeter_mid" || "Core_mid"))
  ?sensor ref:hasExternalReference ?ext .
}

SELECT ?sensor ?tstype ?ext ?tsid WHERE {
  ?z a brick:Zone ; rdfs:label ?label ; brick:hasPoint ?sensor .
  FILTER(?z IN (<http://buildgraph.org/BG_medium_office_2004_0000#Zone_F2_Z03>, <http://buildgraph.org/BG_medium_office_2004_0000#Zone_F2_Z01>))
  OPTIONAL{?sensor brick:type ?tstype}
  OPTIONAL{?sensor ref:hasExternalReference ?ext}
  OPTIONAL{?ext ref:hasTimeseriesId ?tsid}
  ?sensor a ?t .
  BIND(STR(?t) AS ?tstype)
}

SELECT ?sensor ?t ?ext ?tsid WHERE {
  ?z a brick:Zone ; rdfs:label ?label ; brick:hasPoint ?sensor .
  FILTER(?z IN (<http://buildgraph.org/BG_medium_office_2004_0000#Zone_F2_Z03>, <http://buildgraph.org/BG_medium_office_2004_0000#Zone_F2_Z01>))
  OPTIONAL{?sensor ref:hasExternalReference ?ext}
  OPTIONAL{?ext ref:hasTimeseriesId ?tsid}
  ?sensor a ?t .
  BIND(STR(?t) AS ?t)
}

